export const FRAMEWORK_CLASSES = {};

function readNavigator() {
  try {
    if (typeof navigator !== 'undefined' && navigator) return navigator;
  } catch (error) {
    void error;
  }
  return null;
}

function detectPlatformName() {
  const nav = readNavigator();
  const raw = String(nav?.userAgentData?.platform || nav?.platform || '').trim();
  if (!raw) return 'browser';
  return raw.toLowerCase().replace(/\s+/g, '_');
}

function detectSocPlatform() {
  const arch = String(readNavigator()?.userAgentData?.architecture || '').toLowerCase();
  if (arch.includes('arm') || arch === '') return 'qcom';
  return 'qcom';
}

function browserMarketName(nav) {
  const agent = String(nav?.userAgent || '');
  const platform = String(nav?.platform || '');
  const match = /\(([^)]+)\)/.exec(agent);
  if (match) {
    const parts = match[1].split(';').map((part) => part.trim()).filter(Boolean);
    const candidate = parts.find((part) => /^[A-Z][A-Za-z0-9 _.+\-]{2,}$/.test(part) && !/Linux|Windows|Macintosh|Android|Mobile|X11/i.test(part));
    if (candidate) return candidate;
  }
  if (platform) return platform;
  return 'apk.js Browser';
}

function browserModelName(nav) {
  const agent = String(nav?.userAgent || '');
  if (/Edg\//.test(agent)) return 'Edge';
  if (/Firefox\//.test(agent)) return 'Firefox';
  if (/OPR\/|Opera/.test(agent)) return 'Opera';
  if (/Chrome\//.test(agent)) return 'Chrome';
  if (/Safari\//.test(agent)) return 'Safari';
  return 'Browser';
}

function buildSystemProperties() {
  const nav = readNavigator();
  const platform = detectPlatformName();
  const soc = detectSocPlatform();
  const language = String(nav?.language || 'en-US');
  return {
    'ro.product.brand': 'apk.js',
    'ro.product.manufacturer': 'apk.js',
    'ro.product.model': browserModelName(nav),
    'ro.product.nickname': browserMarketName(nav),
    'ro.product.odm.marketname': browserMarketName(nav),
    'ro.product.marketname': browserMarketName(nav),
    'ro.product.device': platform,
    'ro.product.name': platform,
    'ro.product.board': platform,
    'ro.product.cpu.abi': 'arm64-v8a',
    'ro.product.cpu.abilist': 'arm64-v8a,armeabi-v7a,armeabi',
    'ro.build.version.sdk': '31',
    'ro.build.version.release': '12',
    'ro.build.version.incremental': '1',
    'ro.build.id': 'SQ3A.220705.004',
    'ro.build.display.id': 'SQ3A.220705.004',
    'ro.build.fingerprint': `apk.js/${platform}/${platform}:12/SQ3A.220705.004/1:user/release-keys`,
    'ro.build.type': 'user',
    'ro.build.tags': 'release-keys',
    'ro.build.characteristics': 'default',
    'ro.hardware': soc,
    'ro.hardware.chipname': soc,
    'ro.board.platform': soc,
    'ro.soc.model': 'apk.js SoC',
    'ro.soc.manufacturer': 'apk.js',
    'ro.chipname': soc,
    'ro.serialno': 'unknown',
    'ro.bootloader': 'unknown',
    'ro.debuggable': '0',
    'persist.sys.timezone': 'Asia/Shanghai',
    'ro.product.locale': language,
    'ro.product.locale.language': language.split('-')[0] || 'en',
    'ro.product.locale.region': language.split('-')[1] || 'US',
  };
}

let cachedSystemProperties = null;

let cachedSystemFeatures = null;

export function systemFeatureNames() {
  if (cachedSystemFeatures) return cachedSystemFeatures;
  const capabilities = deviceCapabilities();
  const names = [
    'android.hardware.audio.output',
    'android.hardware.audio.low_latency',
    'android.hardware.audio.pro',
    'android.hardware.bluetooth',
    'android.hardware.camera',
    'android.hardware.camera.any',
    'android.hardware.faketouch',
    'android.hardware.fingerprint',
    'android.hardware.location',
    'android.hardware.location.network',
    'android.hardware.screen.landscape',
    'android.hardware.screen.portrait',
    'android.hardware.sensor.accelerometer',
    'android.hardware.sensor.gyroscope',
    'android.hardware.sensor.light',
    'android.hardware.sensor.proximity',
    'android.hardware.touchscreen',
    'android.hardware.type.television',
    'android.hardware.usb.host',
    'android.hardware.wifi',
    'android.software.webview',
  ];
  if (capabilities.touchPoints > 0) names.push('android.hardware.touchscreen.multitouch', 'android.hardware.touchscreen.multitouch.jazzhand');
  if (capabilities.cores >= 2) names.push('android.hardware.sensor.stepcounter');
  return (cachedSystemFeatures = names);
}

function systemProperties() {
  if (cachedSystemProperties) return cachedSystemProperties;
  const built = buildSystemProperties();
  if (readNavigator()) cachedSystemProperties = built;
  return built;
}

function systemProperty(key) {
  const properties = systemProperties();
  if (Object.prototype.hasOwnProperty.call(properties, key)) return properties[key];
  return '';
}

/** 深度优先查找当前持有焦点的子视图（对应 AOSP 的 mFocused 链路）。 */
function findFocusedDescendant(view) {
  if (!view) return null;
  if (view.focused === true) return view;
  for (const child of view.children || []) {
    const found = findFocusedDescendant(child);
    if (found) return found;
  }
  return view.child ? findFocusedDescendant(view.child) : null;
}

/** 把 0..1 的通道值打包成 ARGB 整数（对应 AOSP Color.rgb / Color.argb）。 */
function packArgb(alpha, red, green, blue) {
  const channel = (value) => Math.max(0, Math.min(255, Math.round(Number(value) * 255)));
  return (((channel(alpha) << 24) | (channel(red) << 16) | (channel(green) << 8) | channel(blue)) >>> 0);
}

/** 本模拟器使用「低 32 位 ARGB + 第 32 位标记」的 64 位颜色表示，保证 pack/toArgb 往返一致。 */
function colorLongFromArgb(argb) {
  return (BigInt(argb >>> 0) | (1n << 32n));
}

function colorArgb(color) {
  try {
    return Number(BigInt.asUintN(64, BigInt(color)) & 0xffffffffn) >>> 0;
  } catch (_) {
    return toInt(color) >>> 0;
  }
}

function colorObject(vm, argb) {
  const object = vm.allocateRawObject('Landroid/graphics/Color;');
  object.$peer = { vm, argb: argb >>> 0 };
  return object;
}

/** 构造一个 ComponentName Java 对象（对应 AOSP ComponentName 的 pkg/cls 二元组）。 */
function componentNameObject(vm, pkg, cls) {
  const object = vm.allocateRawObject('Landroid/content/ComponentName;');
  object.$peer = { pkg: String(pkg ?? ''), cls: String(cls ?? '') };
  return object;
}

/** 构造 Toast 对象，字段与 ToastPeer 对齐，供 setGravity/setView 等方法继续使用。 */
function createToast(vm, text, duration) {
  const toast = vm.allocateRawObject('Landroid/widget/Toast;');
  toast.$peer = {
    vm,
    object: toast,
    text: jsString(text) ?? '',
    duration: Number(duration) | 0,
    view: null,
    gravity: 81,
    xOffset: 0,
    yOffset: 0,
    horizontalMargin: 0,
    verticalMargin: 0,
    callbacks: [],
  };
  return toast;
}

/** 按 AOSP Comparable.compareTo 的语义比较两个值（数值、字符串或 Java 对象）。 */
function compareComparables(vm, left, right) {
  if (typeof left === 'number' && typeof right === 'number') return left < right ? -1 : (left > right ? 1 : 0);
  if (typeof left === 'bigint' || typeof right === 'bigint') {
    const a = BigInt(left ?? 0);
    const b = BigInt(right ?? 0);
    return a < b ? -1 : (a > b ? 1 : 0);
  }
  if (typeof left === 'string' && typeof right === 'string') {
    const order = left.localeCompare(right);
    return order < 0 ? -1 : (order > 0 ? 1 : 0);
  }
  if (left && typeof left === 'object') {
    try {
      return vm.invokeByName('compareTo', '(Ljava/lang/Object;)I', left, [right]) | 0;
    } catch {
      // 退回到 identity 比较之外的最合理默认值：无法比较时视为相等。
    }
  }
  if (left === right) return 0;
  return String(comparableText(left)).localeCompare(String(comparableText(right))) < 0 ? -1 : 1;
}

/** 把 Comparable 值转成便于 toString 的文本。 */
function comparableText(value) {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'number' || typeof value === 'bigint' || typeof value === 'string') return String(value);
  if (typeof value?.$string === 'string') return value.$string;
  if (typeof value?.$peer?.text === 'string') return value.$peer.text;
  return '[object]';
}

/** 按 Comparable 的数值/文本语义求哈希，保证相同值的 Range 哈希一致。 */
function hashComparable(value) {
  const text = comparableText(value);
  let hash = 0;
  for (let i = 0; i < text.length; i++) hash = (Math.imul(hash, 31) + text.charCodeAt(i)) | 0;
  return hash;
}

function rangeCreate(vm, lower, upper) {
  const range = vm.allocateRawObject('Landroid/util/Range;');
  range.$peer = { lower, upper };
  return range;
}

/** 对应 AOSP Range.intersect：取两个区间交集，空交集抛 IllegalArgumentException。 */
function rangeIntersect(vm, aLower, aUpper, bLower, bUpper) {
  const lower = compareComparables(vm, aLower, bLower) >= 0 ? aLower : bLower;
  const upper = compareComparables(vm, aUpper, bUpper) <= 0 ? aUpper : bUpper;
  if (compareComparables(vm, lower, upper) > 0) {
    vm.throwException('Ljava/lang/IllegalArgumentException;', `intersect(${comparableText(lower)}, ${comparableText(upper)}) is empty`);
  }
  return rangeCreate(vm, lower, upper);
}

let defaultLocaleList = null;

function localeListObject(vm, locales) {
  const object = vm.allocateRawObject('Landroid/os/LocaleList;');
  object.$peer = { locales: Array.isArray(locales) ? locales : [] };
  return object;
}

/** 读取 Locale 的 BCP-47 标签（模拟器里 Locale peer 保存 language/country）。 */
function localeTagOf(locale) {
  const peer = locale?.$peer || locale || {};
  const direct = peer.tag ?? locale?.$fields?.tag;
  if (typeof direct === 'string' && direct) return String(direct).replace(/_/g, '-');
  const language = String(peer.language ?? locale?.$fields?.language ?? '').toLowerCase();
  const country = String(peer.country ?? locale?.$fields?.country ?? '').toUpperCase();
  return country ? `${language}-${country}` : language;
}

function localeFromTag(vm, tag) {
  const [language, country] = String(tag).replace(/_/g, '-').split('-');
  const object = vm.allocateRawObject('Ljava/util/Locale;');
  object.$peer = { language: (language || 'en').toLowerCase(), country: (country || '').toUpperCase() };
  return object;
}

const WINDOW_INSET_TYPE_GESTURES = 1 << 4;
const WINDOW_INSET_TYPE_MANDATORY_GESTURES = 1 << 5;
const WINDOW_INSET_TYPE_TAPPABLE_ELEMENT = 1 << 6;

/** 按 AOSP WindowInsets.getInsets(type) 的语义，把请求的各类 insets 取并集（逐边取最大值）。 */
function windowInsetsForType(peer, type, includeIgnoringVisibility) {
  const merged = { left: 0, top: 0, right: 0, bottom: 0 };
  const merge = (insets) => {
    if (!insets) return;
    merged.left = Math.max(merged.left, insets.left | 0);
    merged.top = Math.max(merged.top, insets.top | 0);
    merged.right = Math.max(merged.right, insets.right | 0);
    merged.bottom = Math.max(merged.bottom, insets.bottom | 0);
  };
  const stored = peer.insetsTypes?.get(type);
  if (stored) {
    merge(stored);
  } else {
    if (type & WINDOW_INSET_TYPE_GESTURES) {
      merge({ left: peer.gestureLeft, top: peer.gestureTop, right: peer.gestureRight, bottom: peer.gestureBottom });
    }
    if (type & WINDOW_INSET_TYPE_MANDATORY_GESTURES) {
      merge({ left: peer.mandatoryLeft, top: peer.mandatoryTop, right: peer.mandatoryRight, bottom: peer.mandatoryBottom });
    }
    if (type & WINDOW_INSET_TYPE_TAPPABLE_ELEMENT) {
      merge({ left: peer.tappableLeft, top: peer.tappableTop, right: peer.tappableRight, bottom: peer.tappableBottom });
    }
    if (type & ~(WINDOW_INSET_TYPE_GESTURES | WINDOW_INSET_TYPE_MANDATORY_GESTURES | WINDOW_INSET_TYPE_TAPPABLE_ELEMENT)) {
      merge({ left: peer.left, top: peer.top, right: peer.right, bottom: peer.bottom });
    }
  }
  if (includeIgnoringVisibility) merge(peer.insetsIgnoringVisibilityTypes?.get(type));
  return merged;
}

function colorLuminance(argb) {
  return 0.2126 * (((argb >>> 16) & 0xff) / 255) + 0.7152 * (((argb >>> 8) & 0xff) / 255) + 0.0722 * ((argb & 0xff) / 255);
}

/** RGB→HSV，输入输出均为 0..1（对应 AOSP Color.RGBToHSV 的 float 约定）。 */
function rgbToHsv(red, green, blue) {
  const max = Math.max(red, green, blue);
  const min = Math.min(red, green, blue);
  const delta = max - min;
  let hue = 0;
  if (delta > 0) {
    if (max === red) hue = ((green - blue) / delta) % 6;
    else if (max === green) hue = (blue - red) / delta + 2;
    else hue = (red - green) / delta + 4;
    hue /= 6;
    if (hue < 0) hue += 1;
  }
  return [hue, max === 0 ? 0 : delta / max, max];
}

function writeHsv(out, hsv) {
  if (!out?.$data) return;
  for (let i = 0; i < 3; i++) out.$data[i] = hsv[i];
}

function hsvToArgb(alpha, hsv) {
  const values = hsv?.$data || [];
  const hue = ((Number(values[0]) || 0) % 1 + 1) % 1;
  const saturation = Math.max(0, Math.min(1, Number(values[1]) || 0));
  const value = Math.max(0, Math.min(1, Number(values[2]) || 0));
  const sector = hue * 6;
  const index = Math.floor(sector) % 6;
  const fraction = sector - Math.floor(sector);
  const p = value * (1 - saturation);
  const q = value * (1 - saturation * fraction);
  const t = value * (1 - saturation * (1 - fraction));
  const table = [[value, t, p], [q, value, p], [p, value, t], [p, q, value], [t, p, value], [value, p, q]];
  const [r, g, b] = table[index] || [0, 0, 0];
  const alphaByte = Math.max(0, Math.min(255, Math.round(Number(alpha) || 0)));
  return (((alphaByte << 24) | (Math.round(r * 255) << 16) | (Math.round(g * 255) << 8) | Math.round(b * 255)) >>> 0);
}

/** 读取 Java Rect 对象的边界，并补上 Canvas 适配器需要的 width()/height()。 */
function rectPeerBounds(rect) {
  const peer = rect?.$peer ?? rect;
  if (!peer) return null;
  const left = Number(peer.left) || 0;
  const top = Number(peer.top) || 0;
  const right = Number(peer.right) || 0;
  const bottom = Number(peer.bottom) || 0;
  return { left, top, right, bottom, width: () => right - left, height: () => bottom - top };
}

/** 按目标密度换算位图尺寸（对应 AOSP Bitmap.getScaledWidth/Height）。 */
function bitmapScaled(bitmap, targetDensity, useHeight = false) {
  const peer = bitmap?.$peer ?? bitmap ?? {};
  const size = Number(useHeight ? peer.height : peer.width) || 0;
  const density = Number(peer.density) || 160;
  const target = Number(targetDensity) || 160;
  return Math.round((size * target) / density);
}

function makeBitmapObject(vm, width, height, source = null) {
  const object = vm.allocateRawObject('Landroid/graphics/Bitmap;');
  object.$peer = new Bitmap(null, Math.max(0, toInt(width)), Math.max(0, toInt(height)), source);
  return object;
}

/** 创建携带快照数组的 java.util.Iterator（hasNext/next 由 java.util.Iterator 宿主实现）。 */
function snapshotIterator(vm, values) {
  const object = vm.allocateRawObject('Ljava/util/Iterator;');
  object.$peer = { cursor: 0, snapshot: [...(values || [])] };
  return object;
}

function patternMatcherObject(vm, pattern, type) {
  const object = vm.allocateRawObject('Landroid/os/PatternMatcher;');
  object.$peer = { pattern: jsString(pattern), type: toInt(type) };
  return object;
}

function notificationKey(object) {
  const peer = object?.$peer ?? object ?? {};
  return jsString(peer.id ?? peer.mId ?? '');
}

/** 构造宿主侧 MenuItem（用于 android.view.Menu 的 add 系列）。 */
function makeMenuItemObject(vm, { groupId = 0, itemId = 0, order = 0, title = null, titleRes = 0 } = {}) {
  const object = vm.allocateRawObject('Landroid/view/MenuItem;');
  object.$peer = {
    groupId: toInt(groupId),
    itemId: toInt(itemId),
    order: toInt(order),
    title: title ?? null,
    titleRes: toInt(titleRes),
    visible: true,
    enabled: true,
    checkable: false,
    checked: false,
  };
  return object;
}

function menuAddItem(menu, vm, options) {
  const item = makeMenuItemObject(vm, options);
  (menu.items ||= []).push(item);
  return item;
}

function menuAddSubMenu(menu, vm, options) {
  const object = vm.allocateRawObject('Landroid/view/SubMenu;');
  object.$peer = {
    groupId: toInt(options.groupId),
    itemId: toInt(options.itemId),
    order: toInt(options.order),
    title: options.title ?? null,
    titleRes: toInt(options.titleRes),
    visible: true,
    enabled: true,
    items: [],
  };
  (menu.items ||= []).push(object);
  return object;
}

/** 按可用宽度粗略截断文本（对应 TextUtils.ellipsize 的可见结果）。 */
function textEllipsize(text, width, ellipsis) {
  const pixels = Number(width);
  if (!Number.isFinite(pixels) || pixels <= 0) return text;
  const maxChars = Math.max(1, Math.floor(pixels / 8));
  if (text.length <= maxChars) return text;
  return text.slice(0, Math.max(0, maxChars - ellipsis.length)) + ellipsis;
}

function isGraphicChar(code) {
  return code === 0x09 || code === 0x0a || code === 0x0d || code >= 0x20;
}

function isGraphicText(text) {
  for (let i = 0; i < text.length; i++) {
    if (!isGraphicChar(text.charCodeAt(i))) return false;
  }
  return true;
}

function makeRectObject(vm, left, top, right, bottom) {
  const object = vm.allocateRawObject('Landroid/graphics/Rect;');
  const peer = object.$peer || (object.$peer = {});
  peer.rect = new Rect(left | 0, top | 0, right | 0, bottom | 0);
  if (!Object.prototype.hasOwnProperty.call(peer, 'left')) {
    for (const name of ['left', 'top', 'right', 'bottom']) {
      Object.defineProperty(peer, name, {
        configurable: true,
        enumerable: true,
        get: () => peer.rect[name],
        set: (value) => { peer.rect[name] = value | 0; },
      });
    }
  }
  return object;
}

/** Paint.breakText 的共用实现：按字符宽度累加，返回放得下的字符数并把宽度写入 measured。 */
function breakTextImpl(self, data, index, count, maxWidth, measured, forwards) {
  const limit = Number(maxWidth) || 0;
  const start = toInt(index);
  const total = toInt(count);
  let used = 0;
  let taken = 0;
  for (let i = 0; i < total; i++) {
    const offset = forwards ? start + i : start + total - 1 - i;
    const char = String.fromCharCode((data[offset] | 0) & 0xffff);
    const width = self.paint.measureText(char);
    if (used + width > limit) break;
    used += width;
    taken++;
  }
  if (measured?.$data) {
    if (measured.$data.length) measured.$data[0] = numberToFloatBits(used);
  }
  return taken;
}

function appendPathText(self, path, text, x, y) {
  const peer = path?.$peer;
  if (peer) {
    if (!Array.isArray(peer.textRuns)) peer.textRuns = [];
    peer.textRuns.push({ text: String(text || ''), x: Number(x) || 0, y: Number(y) || 0, textSize: Number(self.paint?.textSize) || 14 });
  }
}

function writeTextBounds(self, text, rect) {
  const peer = rect?.$peer;
  if (!peer) return;
  const metrics = self.paint.getFontMetricsInt();
  peer.rect = new Rect(0, metrics.ascent | 0, Math.round(self.paint.measureText(String(text || ''))), metrics.descent | 0);
}

function offsetForAdvance(self, text, advance) {
  const value = String(text || '');
  const limit = Number(advance) || 0;
  let used = 0;
  for (let i = 0; i < value.length; i++) {
    const width = self.paint.measureText(value[i]);
    if (used + width / 2 >= limit) return i;
    used += width;
  }
  return value.length;
}

/** ContentResolver.createSqlQueryBundle：把 SQL 片段塞进 Bundle 的标准键。 */
function conflictSqlBundle(vm, { selection, sortOrder } = {}) {
  const object = vm.allocateRawObject('Landroid/os/Bundle;');
  const map = new Map();
  if (selection != null) map.set('android:query-arg-sql-selection', jsString(selection));
  if (sortOrder != null) map.set('android:query-arg-sql-sort-order', jsString(sortOrder));
  object.$peer = { map };
  return object;
}

/** ContentResolver.openInputStream：file://、content:// 与绝对路径统一走 VIRTUAL_FS 的二进制内容。 */
function contentResolverInputStream(vm, uri) {
  const path = uriVirtualPath(uri);
  if (!path) return null;
  const bytes = VIRTUAL_FS.read(path);
  if (!bytes) return null;
  const object = vm.allocateRawObject('Ljava/io/InputStream;');
  object.$peer = { bytes, offset: 0 };
  return object;
}

const SHELL_LS_LINE = (name) => `lrwxrwxrwx 1 root root 16 2026-01-01 00:00 ${name} -> /dev/block/mmcblk0p1`;

function runShellCommand(command) {
  const text = String(command || '').trim();
  if (text.startsWith('ls ')) {
    const raw = text.slice(3).trim().replace(/^-{1,2}[a-zA-Z]+\s+/, '').trim();
    if (!raw) return '';
    const target = raw.replace(/["']/g, '');
    return VIRTUAL_FS.list(target)
      .map((name) => SHELL_LS_LINE(name))
      .join('\n');
  }
  if (text.startsWith('cat ')) {
    const target = text.slice(4).trim().split(/\s+/)[0].replace(/["']/g, '');
    const value = readFsText(target);
    return value ?? '';
  }
  if (text === 'mount' || text.startsWith('mount ')) {
    return readFsText('/proc/mounts').trim().split('\n').map((line) => {
      const [device, mountPoint, fsType, options] = line.split(/\s+/);
      return `${device} on ${mountPoint} type ${fsType} (${options})`;
    }).join('\n');
  }
  if (text.startsWith('getprop')) {
    const key = text.replace(/^getprop\s*/, '').replace(/["']/g, '').trim();
    if (!key) {
      return Object.entries(systemProperties()).map(([k, v]) => `[${k}]: [${v}]`).join('\n');
    }
    return systemProperty(key);
  }
  if (text.startsWith('echo ')) {
    return text.slice(5).trim().replace(/["']/g, '') + '\n';
  }
  return '';
}

class MessagePeer {
  constructor(vm, object) {
    this.vm = vm;
    this.$object = object;
    this.what = 0;
    this.arg1 = 0;
    this.arg2 = 0;
    this.obj = null;
    this.data = null;
    this.callback = null;
    this.when = 0;
  }
}

/** 读取 Java 对象字段：DEX 侧 iput 写入 $fields，宿主侧写入 peer，二者都要能读到。 */
function peerField(self, name) {
  const fields = self?.$object?.$fields ?? (self?.$fields instanceof Map ? self.$fields : null);
  if (fields instanceof Map && fields.has(name)) return fields.get(name);
  if (fields && typeof fields === 'object' && Object.prototype.hasOwnProperty.call(fields, name)) return fields[name];
  return self?.[name];
}

const messageField = peerField;

