const DATE_PICKER_MODE_SPINNER = 1;
const DATE_PICKER_MODE_CALENDAR = 2;
const DATE_DEFAULT_MIN = -2208988800000; // 1900-01-01T00:00:00Z
const DATE_DEFAULT_MAX = 4102444799000;  // 2099-12-31T23:59:59Z

