  self.$asyncStatus = 'FINISHED';
  if (self.$asyncCancelled) invokeOptional(vm, self, 'onCancelled', '(Ljava/lang/Object;)V', [result]);
  else invokeOptional(vm, self, 'onPostExecute', '(Ljava/lang/Object;)V', [result]);
